#[async_trait]
impl LogBroker for IggyBroker {
    /// Publish an event to a channel. Returns the assigned `Offset`.
    ///
    /// # Errors
    ///
    /// Returns [`PortError::Serialization`] if the envelope cannot be JSON-encoded.
    /// Returns [`PortError::Transport`] if the Iggy producer fails.
    #[instrument(name = "port::LogBroker::publish", skip(self, envelope))]
    async fn publish(&self, envelope: EventEnvelope) -> Result<Offset, PortError> {
        let stream = format!("channel-{}", envelope.channel.id);
        let topic = "events";

        // Create the stream+topic if absent. Without this, publishing to a channel that
        // was never `ensure_channel`ed fails at `producer.init()`, making delivery depend
        // on boot ordering. The stream name derives from the channel id alone, so no
        // tenant or path is needed here — the same reason `subscribe` can address it.
        self.create_stream_and_topic(&stream, topic).await?;

        let payload =
            serde_json::to_vec(&envelope).map_err(|e| PortError::Serialization(e.to_string()))?;

        let msg = IggyMessage::new(None, Bytes::from(payload), None);

        let mut producer = self
            .client
            .producer(&stream, topic)
            .map_err(IggyBrokerError::Transport)?
            .build();

        producer.init().await.map_err(IggyBrokerError::Transport)?;

        producer
            .send(vec![msg])
            .await
            .map_err(IggyBrokerError::Transport)?;

        Ok(envelope.offset)
    }

    /// Open a streaming subscription starting from `from`.
    ///
    /// # Errors
    ///
    /// Returns [`PortError::Transport`] if the Iggy consumer cannot be built or initialized.
    #[instrument(name = "port::LogBroker::subscribe", skip(self))]
    async fn subscribe(
        &self,
        channel_id: ChannelId,
        consumer_id: String,
        from: Offset,
    ) -> Result<EventStream, PortError> {
        let stream = format!("channel-{channel_id}");
        let topic = "events".to_owned();
        let partition = partition_id(&consumer_id);

        let strategy = if from == Offset::BEGINNING {
            PollingStrategy::first()
        } else {
            PollingStrategy::offset(from.0)
        };

        let mut consumer = self
            .client
            .consumer(&consumer_id, &stream, &topic, partition)
            .map_err(IggyBrokerError::Transport)?
            .polling_strategy(strategy)
            .build();

        consumer.init().await.map_err(IggyBrokerError::Transport)?;

        let (tx, rx) = mpsc::channel(CHANNEL_BUF);

        tokio::spawn(async move {
            while let Some(result) = consumer.next().await {
                match result {
                    Ok(msg) => {
                        let decoded: Result<EventEnvelope, _> =
                            serde_json::from_slice(&msg.message.payload);
                        let item = decoded.map_err(|e| PortError::Serialization(e.to_string()));
                        if tx.send(item).await.is_err() {
                            break;
                        }
                    }
                    Err(e) => {
                        let _ = tx.send(Err(PortError::Transport(e.to_string()))).await;
                        break;
                    }
                }
            }
        });

        );

        let mut offset = Offset::BEGINNING;

        loop {
            tokio::select! {
                biased;
                _ = shutdown.changed() => {
                    if *shutdown.borrow() {
                        tracing::info!("cdc consumer received shutdown signal");
                        cancel_token_shutdown.cancel();
                        let _ = event_stream.shutdown().await;
                        break;
                    }
                }
                event_result = event_stream.next_event() => {
                    match event_result {
                        Ok(event) => {
                            let lsn = event.lsn.0;
                            if let Some(change) = self.translate_event(event.event_type) {
                                match change {
                                    Ok(envelope_change) => {
                                        let payload = serde_json::to_value(&envelope_change)
                                            .map_err(|e| CdcError::Stream(e.to_string()))?;
                                        let envelope = EventEnvelope::new(
                                            channel.clone(),
                                            offset,
                                            EventKind::EntityChange,
                                            payload,
                                        );
                                        self.broker.publish(envelope).await?;
                                        event_stream.update_applied_lsn(lsn);
                                        offset = offset.next();
                                    }
                                    Err(e) => {
                                        tracing::warn!(error = %e, "skipping undecoded WAL row");
                                    }
                                }
                            }
                        }
                        Err(pg_walstream::ReplicationError::Cancelled(_)) => {
                            tracing::info!("cdc stream cancelled");
                            break;
                        }
                        Err(e) => {
                            return Err(CdcError::Stream(e.to_string()));
                        }
                    }
                }
            }
        }

        Ok(())
    }

    fn translate_event(
        &self,
        event_type: EventType,
    ) -> Option<Result<frf_domain::EntityChange, DecodeError>> {
        match event_type {
            EventType::Insert {
                schema,
                table,
                data,
                ..
            } => {
                let relation = relation_from_row_data(&schema, &table, &data);
                let cols = columns_from_row_data(&data);
                Some(decode_insert(&relation, self.config.tenant_id, &cols))
            }
            EventType::Update {
                schema,
                table,
                old_data,
                new_data,
                ..
            } => {
                let relation = relation_from_row_data(&schema, &table, &new_data);
                let new_cols = columns_from_row_data(&new_data);
                let old_cols: Option<Vec<Column>> = old_data.as_ref().map(columns_from_row_data);
                Some(decode_update(
                    &relation,
                    self.config.tenant_id,
                    old_cols.as_deref(),
                    &new_cols,
                ))
            }
            EventType::Delete {
                schema,
                table,
                old_data,
                ..
            } => {
                let relation = relation_from_row_data(&schema, &table, &old_data);
                let cols = columns_from_row_data(&old_data);
                Some(decode_delete(&relation, self.config.tenant_id, &cols))
            }
            // Begin / Commit / Relation / Type are protocol overhead — not row changes.
            EventType::Begin { .. }
            | EventType::Commit { .. }
            | EventType::Relation { .. }
            | EventType::Type { .. }
            | EventType::Origin { .. }
            | EventType::Truncate(_)
            | EventType::Message { .. }
            | EventType::StreamStart { .. }
            | EventType::StreamStop
            | EventType::StreamCommit { .. }
            | EventType::StreamAbort { .. }
            | EventType::BeginPrepare { .. }
            | EventType::Prepare { .. }
            | EventType::CommitPrepared { .. }
            | EventType::RollbackPrepared { .. }
            | EventType::StreamPrepare { .. } => None,
        }
    }
}

fn relation_from_row_data(schema: &str, table: &str, data: &pg_walstream::RowData) -> Relation {
    let columns: Vec<String> = data.iter().map(|(name, _)| name.to_string()).collect();
    Relation {
        oid: 0,
        namespace: schema.to_owned(),
        name: table.to_owned(),
        columns,
        pk_index: 0,
    }
}

fn columns_from_row_data(data: &pg_walstream::RowData) -> Vec<Column> {
    data.iter()
        .map(|(name, value)| Column {
            name: name.to_string(),
            value: value.as_str().map(ToOwned::to_owned),
        })
        .collect()
}

use async_trait::async_trait;
use frf_domain::{Channel, ChannelId, Cursor, EventEnvelope, Offset};
use futures_core::Stream;

use crate::error::PortError;

/// A stream of events from a `LogBroker` subscription.
/// Boxed to keep the trait object-safe.
pub type EventStream =
    std::pin::Pin<Box<dyn Stream<Item = Result<EventEnvelope, PortError>> + Send>>;

/// Durable event spine — publish, subscribe, seek, acknowledge.
///
/// Implemented by `frf-broker-iggy`. Wired in `frf-gateway`.
/// Adapter crates MUST instrument their implementations with
/// `#[tracing::instrument(name = "port::LogBroker::<method>")]`.
#[async_trait]
pub trait LogBroker: Send + Sync + 'static {
    /// Publish an event to a channel. Returns the assigned `Offset`.
    async fn publish(&self, envelope: EventEnvelope) -> Result<Offset, PortError>;

    /// Open a streaming subscription starting from `from`.
    ///
    /// Pass `Offset::BEGINNING` to replay from the start.
    async fn subscribe(
        &self,
        channel_id: ChannelId,
        consumer_id: String,
        from: Offset,
    ) -> Result<EventStream, PortError>;

    /// Seek a named cursor to an explicit offset without consuming events.
    async fn seek(&self, cursor: Cursor) -> Result<(), PortError>;

    /// Acknowledge delivery up to and including `offset` for a consumer.
    async fn ack(
        &self,
        channel_id: ChannelId,
        consumer_id: &str,
        offset: Offset,
    ) -> Result<(), PortError>;

    /// Ensure the channel exists; create if absent.
    async fn ensure_channel(&self, channel: Channel) -> Result<(), PortError>;
}

/// Information about a relation (table)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RelationInfo {
    pub relation_id: Oid,
    pub namespace: Arc<str>,
    pub relation_name: Arc<str>,
    pub replica_identity: u8,
    pub columns: Vec<ColumnInfo>,
}

impl RelationInfo {
    #[inline]
    pub fn new(
        relation_id: Oid,
        namespace: String,
        relation_name: String,
        replica_identity: u8,
        columns: Vec<ColumnInfo>,
    ) -> Self {
        Self {
            relation_id,
            namespace: Arc::from(namespace),
            relation_name: Arc::from(relation_name),
            replica_identity,
            columns,
        }
    }

    /// Get the full table name (namespace.relation_name)
    #[inline]
    pub fn full_name(&self) -> String {
        format!("{}.{}", self.namespace, self.relation_name)
    }

    /// Get column by name
    #[inline]
    pub fn get_column_by_name(&self, name: &str) -> Option<&ColumnInfo> {
        self.columns.iter().find(|col| &*col.name == name)
    }

    /// Get column by index
    #[inline(always)]
    pub fn get_column_by_index(&self, index: usize) -> Option<&ColumnInfo> {
        self.columns.get(index)
    }

    /// Get key columns
    #[inline]
    pub fn get_key_columns(&self) -> Vec<&ColumnInfo> {
        self.columns.iter().filter(|col| col.is_key()).collect()
    }

    /// Iterate over the names of key columns (replica-identity columns).
    ///
    /// Zero-allocation: returns an iterator of cheap `Arc<str>` clones so
    /// callers can `.collect()` directly into a `Vec<Arc<str>>` without the
    /// intermediate `Vec<&ColumnInfo>` that `get_key_columns` produces.
    #[inline]
    pub fn key_column_names(&self) -> impl Iterator<Item = Arc<str>> + '_ {
        self.columns
            .iter()
            .filter(|c| c.is_key())
            .map(|c| Arc::clone(&c.name))
    }
}

